ref_dict.theorem pi0norm:
\begin{theorem}
\label{theorem pi0norm}
Let $G$ be any a connected reductively algebraic group over a field $k$ such that $\pi_0^{\A^1}(G)$ has transfers. Then the norm principle holds for $G$. 
\end{theorem}

ref_dict.defn norm principle:
\begin{definition}(\cite[page 2]{barquero-merkurjev})
\label{defn norm principle}
Let $H$ be a torus over $k$. Let $\phi:G\to H$ be a homomorphism. For any separable extension $L/F$ of $k$ fields we have the following diagram 
$$\xymatrix{
G(L) \ar[r]^{\phi_L} & H(L) \ar[d]^{N_{L/F}} \\
G(F) \ar[r]^{\phi_F} & H(F)
}$$
where the right vertical map $N_{L/F}$ is the norm (or the field transfer) map. We say that the norm principle holds for $\phi$, if for any $L/F$ as above, we have 
$$ {\rm Image}(N_{L/F}\circ \phi_L) \subset \phi_K.$$
We say the norm principle holds for $G$ if it holds for any homomorphism from $G$ to a torus over $k$. 
\end{definition}

ref_dict.lemma transfers:
\begin{lemma}
\label{lemma transfers}
Let $T$ be a torus over a field $k$. Then any homomorphism $\KMW_1 \to T$ of strictly $\A^1$-invariant sheaves preserves transfers.
\end{lemma}

ref_dict.theorem intro main:
\begin{theorem}
\label{theorem intro main}
Let $G$ be a quasi-split group over a perfect field $k$.  Then the sheaf $\pi_0^{\A^1}(G)$ is a strictly $\A^1$-invariant sheaf with Voevodsky transfers.
\end{theorem}

ref_dict.corollary norm principle:
\begin{corollary}
\label{corollary norm principle}
The norm principle holds for any quasi-split group over a perfect field $k$.
\end{corollary}

ref_dict.theorem transfers:
\begin{theorem}
\label{theorem transfers}
Let $G$ be a quasi-split group over a perfect field $k$. Fix a Borel subgroup $B$ of $G$ and the corresponding maximal torus $T$ of $G$.  Then the composition of natural maps $T \to G \to \pi_0^{\A^1}(G)$ is an epimorphism of Nisnevich sheaves.  Moreover, the sheaf $\pi_0^{\A^1}(G)$ is a strictly $\A^1$-invariant sheaf with transfers. 
\end{theorem}

ref_dict.theorem quasi-split:
\begin{theorem}
\label{theorem quasi-split}
Let $k$ be a perfect field and let $G$ be a quasi-split algebraic group over $k$.  Fix a Borel subgroup $B$ of $G$ and a maximal torus $T$ of $G$ contained in $B$.  Then $G/B$ is $\#A^1$-connected.  
\end{theorem}

