\begin{theorem}
\label{theorem transfers}
Let $G$ be a quasi-split group over a perfect field $k$. Fix a Borel subgroup $B$ of $G$ and the corresponding maximal torus $T$ of $G$.  Then the composition of natural maps $T \to G \to \pi_0^{\A^1}(G)$ is an epimorphism of Nisnevich sheaves.  Moreover, the sheaf $\pi_0^{\A^1}(G)$ is a strictly $\A^1$-invariant sheaf with transfers. 
\end{theorem}

\begin{lemma}
\label{lemma transfers}
Let $T$ be a torus over a field $k$. Then any homomorphism $\KMW_1 \to T$ of strictly $\A^1$-invariant sheaves preserves transfers.
\end{lemma}

